declare(strict_types=1);require_once dirname(__DIR__).'/config/database.php';require_once dirname(__DIR__).'/includes/auth.php';require_once dirname(__DIR__).'/includes/archive.php';requireRole(2);$unit=(int)($_SESSION['unit_id']??0);if(!verifyCsrfToken()){http_response_code(400);exit('Permintaan tidak valid.');}$id=(int)($_POST['arsip_id']??0);$s=$pdo->prepare('SELECT arsip_id FROM arsip WHERE arsip_id=:id AND unit_id=:u');$s->execute(['id'=>$id,'u'=>$unit]);if(!$s->fetch()){http_response_code(403);exit('Arsip tidak dapat diakses.');}$f=$_FILES['document']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK){exit('Upload gagal.');}$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!archiveUploadAllowed((string)$f['name'],$mime,(int)$f['size'])){exit('File harus PDF/JPG/JPEG/PNG maksimal 20 MB.');}$ext=strtolower(pathinfo((string)$f['name'],PATHINFO_EXTENSION));$relative=archiveStoragePath($ext);$absolute=dirname(__DIR__).DIRECTORY_SEPARATOR.str_replace('/',DIRECTORY_SEPARATOR,$relative);if(!move_uploaded_file($f['tmp_name'],$absolute)){exit('File gagal disimpan.');}$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO file_arsip(arsip_id,nama_file,path_file,ekstensi,mime_type,ukuran_file,checksum,is_primary,uploaded_by) VALUES(:a,:n,:p,:e,:m,:s,:c,0,:u)')->execute(['a'=>$id,'n'=>basename((string)$f['name']),'p'=>$relative,'e'=>$ext,'m'=>$mime,'s'=>(int)$f['size'],'c'=>hash_file('sha256',$absolute),'u'=>(int)$_SESSION['user_id']]);$pdo->prepare('INSERT INTO riwayat_arsip(arsip_id,user_id,aksi,keterangan) VALUES(:a,:u,\'UPLOAD\',\'Dokumen diunggah\')')->execute(['a'=>$id,'u'=>(int)$_SESSION['user_id']]);$pdo->commit();header('Location: arsip-detail.php?id='.$id);}catch(Throwable $e){$pdo->rollBack();@unlink($absolute);exit('Metadata file gagal disimpan.');}